    licenses.append({'source_id': key, 'url': ref['url'], 'source_file': ref['source_file'], 'source_sha256': ref['source_sha256'], 'title': ref['title'], 'source_license_statement': ref['license'], 'usage': 'Numerical fact extraction and private local source verification; broader reproduction rights not inferred.'})
